const email = $input.first().json;

const fromRaw = email.from || '';
const fromMatch = fromRaw.match(/<([^>]+)>/);
const fromEmail = fromMatch ? fromMatch[1].toLowerCase() : fromRaw.toLowerCase().trim();

const subject = email.subject || '';
const textBody = email.text || email.html || '';
const bodySnippet = textBody.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);

console.log('Reply received from:', fromEmail);

return [{
  json: {
    from_email: fromEmail,
    subject: subject,
    body_snippet: bodySnippet,
    raw_text: textBody.slice(0, 2000)
  }
}];

const lead   = $input.first().json;
const sender = $('Extract Sender Info2').first().json;

const text = `${sender.subject || ''} ${sender.raw_text || ''}`.toLowerCase();

const unsubKeywords = ['unsubscribe','remove me','stop emailing','opt out','do not contact','no longer wish','take me off'];
const negativeKeywords = ['not interested','no thanks','no thank you','not at this time','not for us','already have','we have a solution','too busy','please stop','not looking'];

let sentiment = 'positive';
if (unsubKeywords.some(k => text.includes(k))) sentiment = 'unsubscribe';
else if (negativeKeywords.some(k => text.includes(k))) sentiment = 'negative';

console.log('Sentiment:', sentiment, '| Text:', text.slice(0, 100));

return [{ json: {
  lead_id:      lead.lead_id,
  company_name: lead.company_name,
  from_email:   sender.from_email,
  subject:      sender.subject.replace(/'/g, "''"),
  body_snippet: sender.body_snippet.replace(/'/g, "''"),
  sentiment,
  reason: `Keyword: ${sentiment}`
} }];

