const item = $input.first().json;

// Extract sender email from "Name <email@domain>" format
const fromRaw = item.from || '';
const fromEmail = (fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([^\s]+@[^\s]+)/) || [])[1] || fromRaw;

// Get body — IMAP node uses textPlain
const fullText = item.textPlain || item.text || '';

// Strip quoted thread (everything after "On ... wrote:" or "> " lines)
const replyOnly = fullText
  .split(/\r?\n/)
  .filter(line => !line.startsWith('>') && !line.match(/^On .+wrote:$/))
  .join('\n')
  .replace(/\s+$/, '')        // trim trailing whitespace
  .trim();

// Use stripped reply, fall back to full text if stripping removes everything
const raw_text = replyOnly.length > 5 ? replyOnly : fullText.slice(0, 1000);
const body_snippet = raw_text.slice(0, 300);

return [{ json: {
  from_email: fromEmail.toLowerCase().trim(),
  subject: item.subject || '',
  body_snippet,
  raw_text
} }];
